import sys, os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import *
def pages():
    P = []
    P.append(cover("The Early College Questions Checklist", "ask before you commit", "What to ask a college, how to start small, and what I learned finishing an associate degree at 15 and a bachelor's at 17.", art_stairs(300, 180), pill="PRINTABLE PDF · 7 PAGES"))
    P.append(page(head("my route", "How I did it", "One person's path, not a rule. Colleges and policies change, so use this to ask better questions.") +
        '<div class="two"><div>'
        "<p>I left in-person school in 3rd grade, finished high school through FLVS Flex in 2021 at 13, then took the placement test (the PERT, at the time), and enrolled in Palm Beach State College. It wasn't hard to get in, because on paper I had satisfied what was required. I earned my associate degree in political science in 2023, at 15, taking most of my classes online while still joining things on campus. Then I transferred to Florida Atlantic University and earned my bachelor's in 2025, at 17.</p></div>"
        f"<div style='flex:0 0 2.6in'>{art_stairs(250, 160)}</div></div>" +
        box("story", "What it was like", "<p>Starting college on a campus at 13 wasn't bad. Most students were college freshmen, so I didn't stand out. The bigger adjustment came later: taking in-person classes at the university was my first time in a classroom in years, and it took getting used to.</p>") +
        '<div class="two">' + box("worked", "What worked", "<ul><li>Starting with online classes to build confidence</li><li>Joining things on campus, not just classes</li><li>Finding friends who shared my interests</li><li>Being upfront with instructors when I needed something</li></ul>") +
        box("didnt", "What was hard", "<ul><li>The shock when people learned my age</li><li>Moving from online to in-person classes</li><li>Managing my time on my own</li></ul>") + '</div>' +
        f'<p class="fine">Rules about age, placement tests, credits and enrollment vary by college and state and change over time. Always check with the college directly.</p>', "My Route", art=art_compass(90)))
    P.append(page(head("part 1", "Is your child ready for college classes?", "Answer together. This isn't a test; it's a conversation starter.") +
        questions(["Does the learner want to try college classes, not just agree because you do?", "Are they comfortable asking adults questions and asking for help?", "Can they manage a schedule, deadlines and reading on their own, with some support?", "Do they understand what they learn, not only finish it?", "Are they okay being among older students?", "Is there a parent or trusted adult they can talk to when something feels off?", "Can they slow down or withdraw without feeling like they failed?", "Do you have a plan for friends and activities outside class?"]) +
        box("story", "From my experience", "<p>The classes weren't the hardest part. It was being young among older students and managing my own time. Being able to say \"this is hard\" to my parents, without it feeling like failing, mattered most.</p>"), "Readiness for College"))
    P.append(page(head("part 2", "Questions to ask the college", "Write the answer, the date, and who answered. Ask for important answers in writing.") +
        table(["Question", "Answer", "Date / who"], [[q, "", ""] for q in ["What are the age and grade requirements? Any exceptions?", "Which tests, transcripts or interviews are needed?", "What does it cost? Are there programs that help?", "Which credits transfer, and where? (Get it in writing.)", "In person, online, or both?", "Who is our contact? Is there an advisor?", "What role do parents have for a minor?", "How does this affect financial aid and later admissions?", "What is the withdrawal policy if it isn't working?"]], "tall"), "Questions for the College", art=art_stairs(190, 112)))
    P.append(page(head("part 3", "Start small", "A plan for the first term.") +
        "<ol><li><b>Take one or two classes.</b> Think of it as a test of fit.</li><li><b>Pick the format on purpose.</b> Online first, or in person first? Mine was online first.</li><li><b>Read each syllabus on day one,</b> and put every deadline on a calendar.</li><li><b>Introduce yourself to instructors,</b> and decide together how and whether to share your age.</li><li><b>Find one club or group.</b> It made the campus feel like mine.</li><li><b>Check in every month</b> and decide together: add more, stay the same, or pause.</li></ol>" +
        '<div class="two">' + box("worked", "What worked for me", "<p>Joining clubs and organizations on campus, and making friends where we shared interests. At the university, I also made friends with a lot of high schoolers because the campus had a high school on it.</p>") +
        box("didnt", "What I'd watch for", "<p>Overloading the first term. Pushing past stress instead of saying something. And skipping the social side because the classes feel like enough.</p>") + '</div>' +
        box("try", "Money", "<p>I received a few scholarships, including ones specific to my college and one from an honors society. Ask each college about scholarships early, including the ones tied to that school or to clubs and honors programs.</p>"), "Start Small", art=art_book(120, 88)))
    P.append(page(head("keep track", "Your college tracker", "One row per college or program you're exploring.") +
        table(["College / program", "Age & entry rules", "Format", "Credits transfer?", "Cost / aid", "Contact", "Notes"], [[""] * 7 for _ in range(6)], "tall") + field("Our decision, and the date we'll review it", 3), "College Tracker"))
    P.append(page(head("before you go", "Records and next steps") +
        box("plain", "Keep these safe", checks(["High school diploma or completion records", "Official transcripts from every school or program", "A course list with dates and descriptions", "Test results, if any", "Emails and forms from the college", "An activity log (clubs, volunteering, internships)"])) +
        box("story", "From my experience", "<p>In my second-to-last semester I took part in a legislative internship program through the university. I spent the legislative session in Tallahassee, working with a state representative and living on my own for the first time. It was a new step, and my age didn't get in the way. Early college opened doors I didn't know to look for.</p>") + about_author() +
        f'<p class="fine">{DISCLAIMER}</p>', "Records & Next Steps", art=art_sprout(100)))
    return P
if __name__ == "__main__":
    for mode in (False, True): open(os.path.join(HERE, f"early_college{'_print' if mode else ''}.html"), "w").write(build_html(pages(), mode, "The Early College Questions Checklist"))
